266:     case 'Coven': return 1;
267:     case 'Melanesian': { if (!p._tide) p._tide='High'; p._tide = (p._tide==='High')?'Low':'High'; return 1; }
268:     case 'Dreamtime': return Math.min(4, p.back.filter(u=>u.card.type==='Location').length);
269:     case 'Goetia': return 0; // handled on destruction
