445: function resolveInvocation(inst, player, opponent, chosenTarget) {
446:   const card = inst.card;
447:   const effects = card.effects || [];
448:   // LIFO resolution
449:   for (let i = effects.length - 1; i >= 0; i--) {
450:     const e = effects[i];
451:     const action = e.action || '-';
452:     if (action === '-') continue;
453:     const lower = action.toLowerCase();
454:     const nums = action.match(/\d+/g) || [];
455:     const n = nums.length ? parseInt(nums[0]) : 0;
456: 
457:     if (lower.includes('deal') && lower.includes('damage')) {
