566: function declareAttack() {
567:   if (G.turn !== 'player' || G.phase !== 'main') return;
568:   if (attacking.size === 0) { log('No attackers selected.'); return; }
569:   const attackers = [...attacking].map(uid => G.player.front.find(u => u && u.uid === uid)).filter(Boolean);
570:   // tap (Vigilance doesn't tap)
571:   attackers.forEach(u => { if (!hasKeyword(u,'Vigilance')) u.tapped = true; });
572:   // AI blocks
573:   const blockMap = new Map();
574:   const usedBlockers = new Set();
575:   // simple: for each attacker, find best blocker
576:   attackers.forEach(a => {
577:     const candidates = (hasKeyword(a,'Stealth')) ? [] : G.ai.front.filter(u => u && !u.tapped && !usedBlockers.has(u.uid) && canBlock(u,a));
578:     if (candidates.length === 0) { blockMap.set(a.uid, null); return; }
579:     // choose blocker that can kill attacker with least cost, else highest hp
580:     let best = null;
581:     // prefer kill
582:     const killers = candidates.filter(b => effAtk(b) >= effHp(a) - (a.damage||0));
583:     if (killers.length) best = killers.sort((a,b)=>effHp(a)-effHp(b))[0];
584:     else best = candidates.sort((a,b)=>effHp(b)-effHp(a))[0];
585:     if (best) { usedBlockers.add(best.uid); blockMap.set(a.uid, best); }
586:     else blockMap.set(a.uid, null);
587:   });
588:   resolveCombat(G.player, G.ai, attackers, blockMap);
589:   attacking.clear();
590:   G.attackedThisTurn = true;
591:   if (G.player.faction === 'Red Rose Templars' && attackers.length >= 3) {
592:     G.player.front.forEach(u => { if (u.card.faction === 'Red Rose Templars') { u.buffAtk=(u.buffAtk||0)+1; u.buffHp=(u.buffHp||0)+1; } });
593:     log('Crusade! Templar units gain +1/+1.');
594:   }
595:   render();
596:   checkGameOver();
597: }
