599: function resolveCombat(attackerPlayer, defenderPlayer, attackers, blockMap) {
600:   G.lastKiller = (attackerPlayer.faction === 'Oni') ? attackerPlayer : null;
601:   // Preemptive step
602:   // attackers with preemptive/double strike deal damage
603:   attackers.forEach(a => {
604:     if (!isAlive(a)) return;
605:     const b = blockMap.get(a.uid);
606:     if (isPreemptive(a) || hasDoubleStrike(a)) {
607:       if (b && isAlive(b)) {
608:         if (hasKeyword(a,'Deathtouch')) { b.damage = effHp(b); destroyUnit(b, ownerOf(b)); }
609:         else applyDamageUnit(b, effAtk(a), attackerPlayer);
610:       } else if (!b) {
611:         if (!a._dealtSanity) { defenderPlayer.sanity -= effAtk(a); a._dealtSanity = true; if (hasKeyword(a,'Lifesteal')) attackerPlayer.sanity += effAtk(a); }
612:       }
613:     }
614:   });
615:   // blockers with preemptive/double strike deal damage
616:   attackers.forEach(a => {
617:     const b = blockMap.get(a.uid);
618:     if (b && isAlive(b) && (isPreemptive(b) || hasDoubleStrike(b))) {
619:       if (isAlive(a)) applyDamageUnit(a, effAtk(b), defenderPlayer);
620:     }
621:   });
622:   // Overwhelm excess for preemptive? skip
623: 
624:   // Regular step
625:   attackers.forEach(a => {
626:     if (!isAlive(a)) return;
627:     const b = blockMap.get(a.uid);
628:     const purePreemptive = hasKeyword(a,'Preemptive') || hasKeyword(a,'First Strike');
629:     const ds = hasDoubleStrike(a);
630:     if (!purePreemptive && !ds) {
631:       if (b && isAlive(b)) {
632:         const before = effHp(b) - (b.damage||0);
633:         if (hasKeyword(a,'Deathtouch')) { b.damage = effHp(b); destroyUnit(b, ownerOf(b)); }
634:         else applyDamageUnit(b, effAtk(a), attackerPlayer);
635:         if ( (hasKeyword(a,'Overwhelm') || hasKeyword(a,'Trample')) && effAtk(a) > before) {
636:           defenderPlayer.sanity -= (effAtk(a) - before);
637:         }
638:         if (hasKeyword(a,'Lifesteal')) attackerPlayer.sanity += Math.min(effAtk(a), before);
639:       } else if (!b) {
640:         if (!a._dealtSanity) { defenderPlayer.sanity -= effAtk(a); a._dealtSanity = true; if (hasKeyword(a,'Lifesteal')) attackerPlayer.sanity += effAtk(a); }
641:       }
642:     } else if (ds) {
643:       // second hit
644:       if (b && isAlive(b)) {
645:         const before = effHp(b) - (b.damage||0);
646:         if (hasKeyword(a,'Deathtouch')) { b.damage = effHp(b); destroyUnit(b, ownerOf(b)); }
647:         else applyDamageUnit(b, effAtk(a), attackerPlayer);
648:         if ( (hasKeyword(a,'Overwhelm') || hasKeyword(a,'Trample')) && effAtk(a) > before) {
649:           defenderPlayer.sanity -= (effAtk(a) - before);
650:         }
651:       } else if (!b) {
652:         if (!a._dealtSanity) { /* already dealt first in preemptive */ }
653:         else { defenderPlayer.sanity -= effAtk(a); if (hasKeyword(a,'Lifesteal')) attackerPlayer.sanity += effAtk(a); }
654:       }
655:     }
656:   });
657:   // blockers regular damage (non-preemptive)
658:   attackers.forEach(a => {
659:     const b = blockMap.get(a.uid);
660:     if (!b || !isAlive(b)) return;
661:     if (isAlive(a)) {
662:       const blockerPurePreemptive = hasKeyword(b,'Preemptive') || hasKeyword(b,'First Strike');
663:       const blockerDS = hasDoubleStrike(b);
664:       if (!blockerPurePreemptive && !blockerDS) {
665:         if (hasKeyword(b,'Deathtouch')) { a.damage = effHp(a); destroyUnit(a, ownerOf(a)); }
666:         else applyDamageUnit(a, effAtk(b), defenderPlayer);
667:       } else if (blockerDS) {
668:         // second hit for double strike
669:         if (hasKeyword(b,'Deathtouch')) { a.damage = effHp(a); destroyUnit(a, ownerOf(a)); }
670:         else applyDamageUnit(a, effAtk(b), defenderPlayer);
671:       }
672:     }
673:   });
674:   // cleanup flags
675:   attackers.forEach(a => { delete a._dealtSanity; });
676:   G.lastKiller = null;
677: }
