683: function aiTurn() {
684:   if (G.turn !== 'ai') return;
685:   const p = G.ai;
686:   const opp = G.player;
687:   // play cards
688:   let played = true;
689:   while (played) {
690:     played = false;
691:     // sort hand by cost asc
692:     const playable = p.hand.filter(c => canPlayCard(p, c)).sort((a,b)=> (a.card.cost||0)-(b.card.cost||0));
693:     for (const inst of playable) {
694:       if (inst.card.type === 'Unit') {
695:         if (p.front.length >= 5 && p.back.length >= 3) continue;
696:       }
697:       playCardAI(inst);
698:       played = true;
699:       break;
700:     }
701:   }
702:   // attack with all eligible
703:   const eligible = p.front.filter(u => u && !u.tapped && !hasKeyword(u,'Defender') && (u.playedTurn < G.turnNumber || hasKeyword(u,'Haste'))).filter(a => {
704:     const blockers = G.player.front.filter(b=>b && !b.tapped);
705:     if (blockers.length === 0) return true;
706:     const canKill = blockers.some(b => effAtk(a) >= effHp(b));
707:     const survives = blockers.every(b => effHp(a) > effAtk(b));
708:     return canKill || survives || Math.random() < 0.25;
709:   });
710:   if (eligible.length) {
711:     eligible.forEach(u => attacking.add(u.uid));
712:     // reuse declare but for ai
713:     const attackers = [...attacking].map(uid => p.front.find(u=>u&&u.uid===uid)).filter(Boolean);
714:     attackers.forEach(u=>{ if(!hasKeyword(u,'Vigilance')) u.tapped=true; });
715:     // player auto-block
716:     const blockMap = new Map();
717:     const used = new Set();
718:     attackers.forEach(a => {
719:       const candidates = (hasKeyword(a,'Stealth')) ? [] : G.player.front.filter(u=>u && !u.tapped && !used.has(u.uid) && canBlock(u,a));
720:       if (!candidates.length) { blockMap.set(a.uid,null); return; }
721:       // block if can kill or protect sanity: choose highest power
722:       const killers = candidates.filter(b=>effAtk(b) >= effHp(a)-(a.damage||0));
723:       let best = killers.length ? killers.sort((a,b)=>effHp(a)-effHp(b))[0] : candidates.sort((a,b)=>effAtk(b)-effAtk(a))[0];
724:       if (best) { used.add(best.uid); blockMap.set(a.uid,best); }
725:       else blockMap.set(a.uid,null);
726:     });
727:     resolveCombat(p, G.player, attackers, blockMap);
728:     attacking.clear();
729:     render();
730:     checkGameOver();
731:   }
732:   setTimeout(() => {
733:     if (G && G.turn === 'ai') endTurn();
734:   }, 800);
735: }
