import json, urllib.parse, requests, os, time, concurrent.futures, pathlib

ROOT = "/home/runner/work/Project_Chimera/Project_Chimera"
cards = json.load(open(os.path.join(ROOT, "cards.json")))
OUTROOT = os.path.join(ROOT, "assets", "art")

def target_path(c):
    p = c["art_path"]  # res://assets/art/folder/name.png
    # strip res://
    rel = p.replace("res://", "")
    # change ext to .jpg
    base, _ = os.path.splitext(rel)
    return os.path.join(ROOT, base + ".jpg"), base + ".jpg"

def make_prompt(c):
    desc = c.get("visual_description", c["name"])
    # keep prompt reasonable
    prompt = f"{desc}. Fantasy digital card game art illustration, detailed, cinematic lighting, rich colors, no text, no watermark, no logo, no border."
    # truncate
    if len(prompt) > 900:
        prompt = prompt[:900]
    return prompt

def download(c):
    outpath, rel = target_path(c)
    if os.path.exists(outpath) and os.path.getsize(outpath) > 1000:
        return ("skip", c["id"], rel)
    os.makedirs(os.path.dirname(outpath), exist_ok=True)
    prompt = make_prompt(c)
    url = "https://image.pollinations.ai/prompt/" + urllib.parse.quote(prompt) + "?width=256&height=384&nologo=true&model=flux"
    for attempt in range(5):
        try:
            r = requests.get(url, timeout=120)
            if r.status_code == 200 and r.content and len(r.content) > 1000 and r.headers.get("content-type","").startswith("image"):
                with open(outpath, "wb") as f:
                    f.write(r.content)
                return ("ok", c["id"], rel)
            time.sleep(2 + attempt*2)
        except Exception as e:
            time.sleep(3 + attempt*3)
    return ("fail", c["id"], rel)

if __name__ == "__main__":
    todo = cards
    print("total", len(todo))
    done = 0; fails = []
    with concurrent.futures.ThreadPoolExecutor(max_workers=6) as ex:
        futures = {ex.submit(download, c): c for c in todo}
        for fut in concurrent.futures.as_completed(futures):
            status, cid, rel = fut.result()
            done += 1
            if status == "fail":
                fails.append(cid)
            if done % 25 == 0 or status == "fail":
                print(done, status, cid, "fails", len(fails))
    print("DONE", done, "fails", len(fails))
    if fails:
        print("FAILED:", fails[:50])
